/bin/bash -c "python3 - <<'PY'
from PIL import Image, ImageDraw
im=Image.open('first_frame.png').resize((1024,576),Image.Resampling.NEAREST)
d=ImageDraw.Draw(im)
# coordinates grid every 10px source
for x in range(0,256,10):
 d.line((x*4,0,x*4,576), fill=(255,0,0) if x%50==0 else (180,30,30), width=1)
 if x%20==0: d.text((x*4+2,2),str(x),fill=(255,255,0))
for y in range(0,144,10):
 d.line((0,y*4,1024,y*4), fill=(255,0,0) if y%50==0 else (180,30,30), width=1)
 if y%20==0: d.text((2,y*4+2),str(y),fill=(255,255,0))
im.save('.tmp/grid.png')
PY"
